template <typename Iter, typename Pred>
auto partition_copy_if(Iter first, Iter last, Pred pred) {
  using T = typename std::iterator_traits<Iter>::value_type;
  std::vector<T> matched, rest;
  for (; first != last; ++first) {
    (pred(*first) ? matched : rest).push_back(*first);
  }
  return std::pair{std::move(matched), std::move(rest)};
}

class ScopeGuard {
 public:
  explicit ScopeGuard(std::function<void()> fn) : fn_(std::move(fn)) {}
  ~ScopeGuard() { if (fn_) fn_(); }
  ScopeGuard(const ScopeGuard&) = delete;
  ScopeGuard& operator=(const ScopeGuard&) = delete;
 private:
  std::function<void()> fn_;
};

template <typename T>
concept Addable = requires(T a, T b) {
  { a + b } -> std::convertible_to<T>;
};

template <Addable T>
T sum(T a, T b) { return a + b; }
